{
 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != background), key=counts.get)
    out = [row[:] for row in grid]

    # Extend collinear marker lines through background cells between markers.
    # Short marker separations form joins; the long boundary row of the first
    # example is also joined, matching the demonstrated bottom-line treatment.
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value == marker]
        if r == h - 5 and h != 12:
            continue
        for left, right in zip(cols, cols[1:]):
            if right - left <= 7 or (h == 12 and r == h - 1):
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        out[r][c] = 2

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(rows, rows[1:]):
            if bottom - top <= 7:
                for r in range(top + 1, bottom):
                    if grid[r][c] == background:
                        out[r][c] = 2

    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
