 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    values = {v for row in grid for v in row}
    bg = max(values, key=lambda v: sum(row.count(v) for row in grid))
    fg = max((v for v in values if v != bg), key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]

    # Each row and column with marker dots is completed across the marker
    # bounding box, preserving markers and changing background cells only.
    for r in range(r0, r1 + 1):
        cols = [c for rr, c in pts if rr == r]
        if cols:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
        rows = [r for r, cc in pts if cc == c]
        if rows:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
