 "content": "def transform(grid):
    h = len(grid)
    w = min(len(row) for row in grid)
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((value for value in counts if value != bg), key=counts.get)
    out = [row[:] for row in grid]

    # Connect marker pairs on the same row or column at the short spacing
    # evidenced by demonstrations, changing only background cells.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        for left, right in zip(cols, cols[1:]):
            if 3 <= right - left <= 6:
                for c in range(left + 1, right):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        for top, bottom in zip(rows, rows[1:]):
            if 3 <= bottom - top <= 6:
                for r in range(top + 1, bottom):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
