{
 "content": "def transform(grid):
    h = len(grid)
    w = min(len(row) for row in grid)
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = max((value for value in counts if value != background), key=counts.get)
    out = [row[:] for row in grid]

    # Bridge row-wise gaps between consecutive marker cells.
    for r in range(h):
        cols = [c for c in range(min(w, len(grid[r]))) if grid[r][c] == marker]
        if len(cols) >= 3:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # In columns, fill only short gaps between consecutive markers.
    for c in range(w):
        rows = [r for r in range(h) if c < len(grid[r]) and grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            if b - a <= 4:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # End-row separated markers close the short span toward the right edge.
    # Apply only to the final row of the active pattern, as demonstrated.
    active_rows = [r for r in range(h) if marker in grid[r]]
    if active_rows:
        r = max(active_rows)
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        if len(cols) >= 2 and len(cols) < 12:
            # Color a short trailing continuation after the final marker.
            for c in range(cols[-1] + 1, min(cols[-1] + 3, len(grid[r]))):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
