 "content": "def transform(grid):
    h = len(grid)
    w = min(len(row) for row in grid)
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = max((value for value in counts if value != background), key=counts.get)
    out = [row[:] for row in grid]

    # In a marker row, bridge any two consecutive markers separated by
    # background. Marker cells and non-background cells are preserved.
    for r in range(h):
        cols = [c for c in range(min(w, len(grid[r]))) if grid[r][c] == marker]
        for left, right in zip(cols, cols[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
